<x-tool-paper x-data="{
    bot: '*',
    allow: '/',
    disallow: '/admin/\n/api/\n/drafts/',
    sitemap: 'https://example.com/sitemap.xml',
    crawlDelay: '',
    copied: false,
    get robotsContent() {
        let lines = [
            '# robots.txt generated by Tool4SaaS',
            '# Local-first client tool',
            ''
        ];
        lines.push('User-agent: ' + (this.bot || '*'));
        if (this.allow.trim()) {
            this.allow.split('\n').filter(Boolean).forEach(p => lines.push('Allow: ' + p.trim()));
        }
        if (this.disallow.trim()) {
            this.disallow.split('\n').filter(Boolean).forEach(p => lines.push('Disallow: ' + p.trim()));
        }
        if (this.crawlDelay) {
            lines.push('Crawl-delay: ' + this.crawlDelay);
        }
        if (this.sitemap.trim()) {
            lines.push('');
            lines.push('Sitemap: ' + this.sitemap.trim());
        }
        return lines.join('\n');
    },
    copy() {
        navigator.clipboard.writeText(this.robotsContent);
        this.copied = true;
        setTimeout(() => this.copied = false, 2000);
    },
    download() {
        const blob = new Blob([this.robotsContent], { type: 'text/plain;charset=utf-8' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'robots.txt';
        a.click();
    }
}">
    <div class="space-y-6">
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div class="form-control">
                <label class="label py-1"><span class="label-text font-bold text-xs uppercase tracking-wider text-base-content/60 font-mono">Crawler Target</span></label>
                <select x-model="bot" class="select select-bordered rounded-xl w-full text-sm font-mono">
                    <option value="*">All Bots (*)</option>
                    <option value="Googlebot">Googlebot</option>
                    <option value="Bingbot">Bingbot</option>
                    <option value="GPTBot">GPTBot (OpenAI)</option>
                    <option value="ClaudeBot">ClaudeBot (Anthropic)</option>
                    <option value="PerplexityBot">PerplexityBot</option>
                </select>
            </div>
            <div class="sm:col-span-2">
                <label class="block text-xs font-bold uppercase tracking-wider text-base-content/60 font-mono mb-1">XML Sitemap URL</label>
                <input type="url" x-model="sitemap" placeholder="https://yourwebsite.com/sitemap.xml" class="input input-bordered rounded-xl w-full text-sm font-mono" />
            </div>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
                <label class="block text-xs font-bold uppercase tracking-wider text-base-content/60 font-mono mb-1">Allowed Directives (1 per line)</label>
                <textarea x-model="allow" rows="4" class="textarea textarea-bordered rounded-xl w-full text-sm font-mono"></textarea>
            </div>
            <div>
                <label class="block text-xs font-bold uppercase tracking-wider text-base-content/60 font-mono mb-1">Disallowed Paths (1 per line)</label>
                <textarea x-model="disallow" rows="4" class="textarea textarea-bordered rounded-xl w-full text-sm font-mono"></textarea>
            </div>
        </div>

        {{-- Polarity-Flipped Dark Hero Display --}}
        <div class="p-6 sm:p-9 rounded-3xl bg-[#0e0f0c] text-white border border-[#242a20] shadow-sm space-y-4">
            <div class="flex items-center justify-between">
                <span class="text-xs font-bold uppercase tracking-wider text-[#868685] font-mono">Generated robots.txt Preview</span>
                <div class="flex items-center gap-2">
                    <button
                        type="button"
                        @click="copy()"
                        class="px-4 py-1.5 rounded-full bg-base-200 text-white hover:bg-base-300 text-xs font-bold transition-all"
                    >
                        <span x-text="copied ? 'Copied!' : 'Copy'"></span>
                    </button>
                    <button
                        type="button"
                        @click="download()"
                        class="px-4 py-1.5 rounded-full bg-primary text-primary-content hover:bg-primary/90 text-xs font-bold transition-all shadow-xs"
                    >
                        Download robots.txt
                    </button>
                </div>
            </div>
            <textarea x-model="robotsContent" readonly rows="7" class="textarea textarea-bordered rounded-2xl w-full text-xs font-mono bg-black/60 text-primary border-[#242a20] p-4"></textarea>
        </div>
    </div>
</x-tool-paper>
